import React from "react";
import { Link } from "react-router-dom";
import "../index.css";

const CarouselCard = ({ id, title, icon }) => {
  return (
    <Link
      to={`/video/${id}`}  // Use Link para navegação
      className="flex items-center justify-center bg-gradient-to-b from-[#B95758] to-[#e14d3a] 
           text-white shadow-2xl rounded-lg w-full max-w-sm h-32 p-5 m-1"
    >
      <div className="flex items-center space-x-3">
        <img
          src={icon}
          alt={title}
          className="w-24 h-24 object-contain"
        />
        <h1 className="text-2xl font-bold">{title}</h1>
      </div>
    </Link>
  );
};

export default CarouselCard;
